// Generic, read-only serializer for a Go parser's native model (see ../../bridges.ts).
// It reads exported and unexported fields by reflection under their own names, prints
// named integer constants by their declared identifier (tables generated by enumgen.go
// from the project's own const declarations), drops `parent` back-pointers and any other
// pointer back to an object still being written, and keeps Go maps as Maps.
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"sort"
	"strconv"
	"unsafe"
)

type enumEntry = struct {
	T reflect.Type
	V int64
	N string
}

type ptrKey struct {
	p uintptr
	t reflect.Type
}

type encoder struct {
	buf   bytes.Buffer
	enums map[reflect.Type]map[int64]string
	open  map[ptrKey]bool
}

func newEncoder(tables ...[]enumEntry) *encoder {
	e := &encoder{enums: map[reflect.Type]map[int64]string{}, open: map[ptrKey]bool{}}
	for _, table := range tables {
		for _, entry := range table {
			if e.enums[entry.T] == nil {
				e.enums[entry.T] = map[int64]string{}
			}
			if _, seen := e.enums[entry.T][entry.V]; !seen { // first declared name wins for aliases
				e.enums[entry.T][entry.V] = entry.N
			}
		}
	}
	return e
}

func (e *encoder) str(s string) {
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	enc.Encode(s)
	e.buf.Write(bytes.TrimSuffix(b.Bytes(), []byte{'\n'}))
}

// accessible returns a usable copy of a pointer read from an unexported field, so its
// methods can be called; reading through it never writes.
func accessible(v reflect.Value) reflect.Value {
	return reflect.NewAt(v.Type().Elem(), unsafe.Pointer(v.Pointer()))
}

// orderedMap recognizes a pointer to an insertion-ordered map type exposing Keys() and Get(k) (v, ok).
func orderedMap(v reflect.Value) (keys []reflect.Value, get func(reflect.Value) reflect.Value, ok bool) {
	t := v.Type()
	km, hasKeys := t.MethodByName("Keys")
	gm, hasGet := t.MethodByName("Get")
	if !hasKeys || !hasGet || km.Type.NumIn() != 1 || km.Type.NumOut() != 1 || km.Type.Out(0).Kind() != reflect.Slice ||
		gm.Type.NumIn() != 2 || gm.Type.NumOut() != 2 || gm.Type.Out(1).Kind() != reflect.Bool {
		return nil, nil, false
	}
	p := accessible(v)
	ks := p.MethodByName("Keys").Call(nil)[0]
	for i := 0; i < ks.Len(); i++ {
		keys = append(keys, ks.Index(i))
	}
	g := p.MethodByName("Get")
	return keys, func(k reflect.Value) reflect.Value { return g.Call([]reflect.Value{k})[0] }, true
}

func (e *encoder) named(v reflect.Value, n int64) bool {
	if names, ok := e.enums[v.Type()]; ok {
		if name, ok := names[n]; ok {
			e.str(name)
			return true
		}
	}
	if v.Type().PkgPath() == "" {
		return false
	}
	c := reflect.New(v.Type()).Elem() // a fresh copy, so String() may be called on an unexported value
	if c.CanInt() {
		c.SetInt(v.Int())
	} else {
		c.SetUint(v.Uint())
	}
	if s, ok := c.Interface().(fmt.Stringer); ok {
		e.str(s.String())
		return true
	}
	return false
}

func (e *encoder) nativeMap(entries [][2]reflect.Value) {
	e.buf.WriteString(`{"__tridentNativeMap":[`)
	for i, kv := range entries {
		if i > 0 {
			e.buf.WriteByte(',')
		}
		e.buf.WriteByte('[')
		e.value(kv[0])
		e.buf.WriteByte(',')
		e.value(kv[1])
		e.buf.WriteByte(']')
	}
	e.buf.WriteString(`]}`)
}

func (e *encoder) backReference(f reflect.StructField, v reflect.Value) bool {
	if v.Kind() != reflect.Pointer {
		return false
	}
	return f.Name == "parent" || f.Name == "Parent" || !v.IsNil() && e.open[ptrKey{v.Pointer(), v.Type()}]
}

func (e *encoder) value(v reflect.Value) {
	switch v.Kind() {
	case reflect.Invalid:
		e.buf.WriteString("null")
	case reflect.Pointer:
		if v.IsNil() {
			e.buf.WriteString("null")
			return
		}
		if keys, get, ok := orderedMap(v); ok {
			entries := make([][2]reflect.Value, len(keys))
			for i, k := range keys {
				entries[i] = [2]reflect.Value{k, get(k)}
			}
			e.nativeMap(entries)
			return
		}
		key := ptrKey{v.Pointer(), v.Type()}
		if e.open[key] { // a cycle reached through a list or map rather than a field
			e.buf.WriteString("null")
			return
		}
		e.open[key] = true
		e.value(v.Elem())
		delete(e.open, key)
	case reflect.Interface:
		if v.IsNil() {
			e.buf.WriteString("null")
		} else {
			e.value(v.Elem())
		}
	case reflect.Struct:
		e.buf.WriteByte('{')
		first := true
		for i := 0; i < v.NumField(); i++ {
			f, fv := v.Type().Field(i), v.Field(i)
			if f.Name == "_" || e.backReference(f, fv) {
				continue
			}
			if !first {
				e.buf.WriteByte(',')
			}
			first = false
			e.str(f.Name)
			e.buf.WriteByte(':')
			e.value(fv)
		}
		e.buf.WriteByte('}')
	case reflect.Slice, reflect.Array:
		e.buf.WriteByte('[')
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				e.buf.WriteByte(',')
			}
			e.value(v.Index(i))
		}
		e.buf.WriteByte(']')
	case reflect.Map:
		entries := make([][2]reflect.Value, 0, v.Len())
		sortKeys := make([]string, 0, v.Len())
		for it := v.MapRange(); it.Next(); {
			entries = append(entries, [2]reflect.Value{it.Key(), it.Value()})
			sub := &encoder{enums: e.enums, open: map[ptrKey]bool{}}
			sub.value(it.Key())
			sortKeys = append(sortKeys, sub.buf.String())
		}
		index := make([]int, len(entries))
		for i := range index {
			index[i] = i
		}
		sort.SliceStable(index, func(a, b int) bool { return sortKeys[index[a]] < sortKeys[index[b]] })
		sorted := make([][2]reflect.Value, len(entries))
		for i, j := range index {
			sorted[i] = entries[j]
		}
		e.nativeMap(sorted)
	case reflect.String:
		e.str(v.String())
	case reflect.Bool:
		e.buf.WriteString(strconv.FormatBool(v.Bool()))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		if !e.named(v, v.Int()) {
			e.buf.WriteString(strconv.FormatInt(v.Int(), 10))
		}
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		if v.Uint() > math.MaxInt64 || !e.named(v, int64(v.Uint())) {
			e.buf.WriteString(strconv.FormatUint(v.Uint(), 10))
		}
	case reflect.Float32, reflect.Float64:
		f := v.Float()
		if math.IsNaN(f) || math.IsInf(f, 0) {
			e.buf.WriteString("null")
		} else {
			e.buf.WriteString(strconv.FormatFloat(f, 'g', -1, 64))
		}
	default:
		panic(fmt.Sprintf("model holds a %s (%s), which has no JSON form", v.Kind(), v.Type()))
	}
}

// encode returns the JSON text of a model value.
func (e *encoder) encode(model any) string {
	e.buf.Reset()
	e.value(reflect.ValueOf(model))
	return e.buf.String()
}
